double totalVleftaPaTvshPerArtPaTvsh = 0;
private void xrLabel32_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
   xrLabel32.Visible = false;
            object nipti = GetCurrentColumnValue("transp_nipt");
            if (nipti != DBNull.Value)
            {
                int gjatesiNipt = nipti.ToString().Length;
                Char[] arr = new Char[gjatesiNipt];
                arr = nipti.ToString().ToCharArray();
                for (int i = 0; i < gjatesiNipt; i++)
                {
                    XRLabel label = FindControl("tr" + (i + 1), true) as XRLabel;
                    if (label != null)
                        label.Text = arr[i].ToString();
                }
            }
}

