private void xrLabel44_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
  furnizimeTePaTatueshme = totalVleftaPaTvshPerArtPaTvsh * (1 - (Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) / Convert.ToDouble(GetCurrentColumnValue("TOTALI"))));
            xrLabel44.Text = String.Format("{0:n2}", Math.Round(furnizimeTePaTatueshme, 2));
}

private void xrLabel45_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 furnizimeTeTatueshme = totalVleftaPaTvshPerArtMeTvsh * (1 - (Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) / Convert.ToDouble(GetCurrentColumnValue("TOTALI"))));
            xrLabel45.Text = String.Format("{0:n2}", Math.Round(furnizimeTeTatueshme, 2));
}

private void xrTableCell14_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            if (GetCurrentColumnValue("tvsh").ToString() != "" && Convert.ToDouble(GetCurrentColumnValue("tvsh")) != 0)
                totalVleftaPaTvshPerArtMeTvsh += Convert.ToDouble(GetCurrentColumnValue("VLEFTAPATVSH"));
            else
                totalVleftaPaTvshPerArtPaTvsh += Convert.ToDouble(GetCurrentColumnValue("VLEFTAPATVSH"));
}

private void xrTableCell13_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {

            if (sasia_total != 0)
            {
                e.Result = String.Format("{0:n3}", shuma / sasia_total);
                e.Handled = true;
            }
            else
            {
                e.Result = 0;
                e.Handled = true;
            }
}

private void xrTableCell13_SummaryReset(object sender, System.EventArgs e) {
sasia_total = 0;
            shuma = 0;
}

private void xrTableCell13_SummaryRowChanged(object sender, System.EventArgs e) {
double sasia = Convert.ToDouble(GetCurrentColumnValue("SASIA"));
            double cmim = Convert.ToDouble(GetCurrentColumnValue("CmimiPaTvshTrupi"));
            shuma += sasia * cmim;
            sasia_total += sasia;
}
